function calcEmaSeries(values, period) {
	if (values.length === 0) return [];
	const k = 2 / (period + 1);
	const result = [values[0]];
	for (let i = 1; i < values.length; i++) result.push(values[i] * k + result[i - 1] * (1 - k));
	return result;
}
function calcRsiSeries(closes, period = 14) {
	if (closes.length <= period) return closes.map(() => 50);
	const rsis = new Array(closes.length).fill(50);
	let gainSum = 0;
	let lossSum = 0;
	for (let i = 1; i <= period; i++) {
		const diff = closes[i] - closes[i - 1];
		if (diff >= 0) gainSum += diff;
		else lossSum += Math.abs(diff);
	}
	let avgGain = gainSum / period;
	let avgLoss = lossSum / period;
	rsis[period] = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss);
	for (let i = period + 1; i < closes.length; i++) {
		const diff = closes[i] - closes[i - 1];
		const gain = diff > 0 ? diff : 0;
		const loss = diff < 0 ? Math.abs(diff) : 0;
		avgGain = (avgGain * (period - 1) + gain) / period;
		avgLoss = (avgLoss * (period - 1) + loss) / period;
		rsis[i] = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss);
	}
	return rsis;
}
function calcAtrSeries(candles, period = 14) {
	if (candles.length === 0) return [];
	const trs = [candles[0].h - candles[0].l];
	for (let i = 1; i < candles.length; i++) {
		const cur = candles[i];
		const prevClose = candles[i - 1].c;
		trs.push(Math.max(cur.h - cur.l, Math.abs(cur.h - prevClose), Math.abs(cur.l - prevClose)));
	}
	return calcEmaSeries(trs, period);
}
