	let convictionTier = "ESTANDAR";
	const tags = [];
	if (deepAnalysis.unifiedScore >= 80 && deepAnalysis.firedStrategies.length >= 2) {
		sizeMultiplier *= 1.25;
		convictionTier = "A+";
		tags.push("Confluencia Alta 80–100 (size 1.25x)");
	} else if (deepAnalysis.unifiedScore >= 65) {
		sizeMultiplier *= 1;
		convictionTier = "ESTANDAR";
		tags.push("Señal Válida 65–79");
	} else {
		sizeMultiplier *= .8;
		convictionTier = "AGRESIVO";
		tags.push("Cautela 50–64 (size 0.80x)");
	}
	if (deepAnalysis.sweepDirection && deepAnalysis.sweepDirection !== "NONE") tags.push(deepAnalysis.sweepDirection === "LONG_SWEEP" ? "Caza-Barrida LONG (stops liquidados)" : "Caza-Barrida SHORT (trampa alcista)");
